const pageLabels={overview:'Beranda',products:'Daftar Barang',categories:'Kategori',suppliers:'Supplier',settings:'Pengaturan',profile:'Profil'};
let db = loadData();
let activePage = 'overview';
let query = '';
let productFilter = 'Semua';
let activeModal = null;
let supa = loadConfig();
let itemsRemoteColumns = null;
let pendingProductImage = '';
let busy = false;
let splashComplete = false;
let authToken = sessionStorage.getItem('zaven-access-token') || '';
let authUser = (()=>{try{return JSON.parse(sessionStorage.getItem('zaven-auth-user')||'null')}catch{return null}})();
let deferredInstallPrompt = null;
let zavenInstalled = window.matchMedia('(display-mode: standalone)').matches || navigator.standalone === true;
function installButtonMarkup(place='login'){
  if(zavenInstalled)return '';
  return place==='top'
    ? `<button type="button" class="btn btn-install top-install" data-action="install-app" aria-label="Pasang aplikasi ZAVEN" title="Pasang ZAVEN">${I('download',14)}<span>Instal aplikasi</span></button>`
    : `<button type="button" class="btn install-app-button" data-action="install-app">${I('download',15)} Pasang aplikasi di perangkat ini</button>`;
}
function removeInstallButtons(){$$('[data-action="install-app"]').forEach(button=>button.remove())}


function loadData(){try{const saved=JSON.parse(localStorage.getItem(STORE));return saved&&saved.products? saved:structuredClone(sample)}catch{return structuredClone(sample)}}
function saveData(){localStorage.setItem(STORE,JSON.stringify(db))}
function loadConfig(){try{const cfg=JSON.parse(localStorage.getItem(CONFIG));if(!cfg)return null;if(!cfg.productsTable||cfg.productsTable==='products')cfg.productsTable='items';if(cfg.categoriesTable==='categories')cfg.categoriesTable='';if(cfg.suppliersTable==='suppliers')cfg.suppliersTable='';return cfg}catch{return null}}
function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function rupiah(n){return new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(Number(n)||0)}
function rupiahCompact(n){n=Number(n)||0;return n>=1000000?`Rp ${(n/1000000).toFixed(1).replace('.',',')} jt`:rupiah(n)}
function shortPrice(n){return new Intl.NumberFormat('id-ID').format(Number(n)||0)}
function dateID(s){if(!s)return '—';const d=new Date(s+'T00:00:00');return new Intl.DateTimeFormat('id-ID',{day:'2-digit',month:'short',year:'numeric'}).format(d)}
function todayISO(){return new Date().toISOString().slice(0,10)}
function initials(s){return String(s||'Zaven').trim().split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase()}
function lowStock(){return db.products.filter(p=>Number(p.stock)<=5)}
function statusBadge(p){if(Number(p.stock)<=0)return `<span class="status status-out"><i class="status-dot"></i>Habis</span>`;if(Number(p.stock)<=5)return `<span class="status status-low"><i class="status-dot"></i>Stok Menipis</span>`;return `<span class="status status-ok"><i class="status-dot"></i>Tersedia</span>`}
function thumb(p){if(p.image)return `<div class="item-thumb photo-thumb"><img src="${esc(p.image)}" alt="" loading="lazy" onerror="this.style.display='none'"></div>`;const icon=p.icon|| (p.category==='Elektronik'?'laptop':'box');const palette={laptop:'',mouse:'cyan',keyboard:'purple',printer:'orange',phone:'cyan',box:'purple'};return `<div class="item-thumb ${palette[icon]||''}">${I(icon,18)}</div>`}
function connectionLabel(){return supa?`<span class="connection-pill connected"></span> Supabase terhubung`:`<span class="connection-pill"></span> Mode browser`}
function currentUserName(){return sessionStorage.getItem('zaven-display-name')||authUser?.user_metadata?.full_name||authUser?.email||localStorage.getItem('zaven-profile-name')||'Rahmatul Satria Ardaniyah'}
function hasAppSession(){return sessionStorage.getItem('zaven-session')==='demo'||!!authToken}
function navLink(id,name,ic,count=''){return `<button class="nav-link ${activePage===id?'active':''}" data-page="${id}">${I(ic,18)}<span>${name}</span>${count?`<span class="nav-count">${count}</span>`:''}</button>`}
function shell(content){const user=currentUserName();return `<div class="shell"><aside class="sidebar"><div class="brand"><div class="brand-mark"><svg viewBox="0 0 32 32" fill="none"><path d="M8 7h17L8 25h17" stroke="white" stroke-width="4.5" stroke-linecap="square" stroke-linejoin="round"/><path d="M22.2 25 26 20.9" stroke="#9fd8ff" stroke-width="3.3" stroke-linecap="round"/></svg></div><div class="brand-copy"><div class="brand-name">ZAVEN</div><div class="brand-sub">Smart Inventory</div></div></div><div class="nav-caption">Menu Utama</div><nav class="nav-group">${navLink('overview','Beranda','grid')}${navLink('products','Barang','box',db.products.length)}${navLink('categories','Kategori','layers')}${navLink('suppliers','Supplier','truck')}</nav><div class="nav-divider"></div><div class="nav-caption">Preferensi</div><nav class="nav-group">${navLink('settings','Pengaturan','settings')}${navLink('profile','Profil','user')}</nav><div class="sidebar-spacer"></div><div class="help-card"><div class="help-badge">${I('spark',16)}</div><strong>Kelola stok tanpa ribet</strong><p>Semua data inventaris tersusun rapi dalam satu dashboard.</p><button data-action="settings">Atur koneksi data ${I('arrow',12)}</button></div><div class="profile"><div class="avatar">${esc(initials(user))}</div><div class="profile-copy"><strong>${esc(user)}</strong><span>${authToken?'Akun Supabase':'Administrator · Demo lokal'}</span></div><button class="profile-menu" data-action="profile">${I('down',16)}</button></div></aside><main class="main"><header class="topbar"><div class="crumb"><b>ZAVEN</b><span style="padding:0 7px;color:#c5ccd7">/</span>${esc(pageLabels[activePage]||'Beranda')}</div><div class="top-actions"><label class="global-search">${I('search',16)}<input id="global-search" placeholder="Cari barang, kategori..." value="${esc(query)}" aria-label="Pencarian global"></label><button class="icon-button" data-action="notifications" aria-label="Notifikasi">${I('bell',17)}${lowStock().length?'<i class="notification-dot"></i>':''}</button>${installButtonMarkup('top')}<button type="button" class="top-avatar" data-action="group-profile" aria-label="Buka Nama Kelompok" title="Buka daftar nama kelompok"><span class="top-avatar-initials">${esc(initials(user))}</span><span class="top-avatar-label">Nama Kelompok</span></button></div></header><section class="page">${content}</section></main><nav class="mobile-nav">${[['overview','Beranda','grid'],['products','Barang','box'],['categories','Kategori','layers'],['suppliers','Supplier','truck'],['profile','Profil','user']].map(([id,n,ic])=>`<button class="${activePage===id?'active':''}" data-page="${id}">${I(ic,17)}${n}</button>`).join('')}</nav><div id="modal-root"></div><div class="toast-stack" id="toast-stack"></div></div>`}
function pageHead(title,subtitle,actions='',eyebrow='ZAVEN SMART INVENTORY'){return `<div class="page-head"><div><p class="eyebrow">${eyebrow}</p><h1 class="page-title">${title}</h1><p class="page-description">${subtitle}</p></div>${actions?`<div class="page-actions">${actions}</div>`:''}</div>`}
function statCard(label,value,foot,ic,tint=''){return `<article class="stat-card"><div class="stat-top"><span class="stat-label">${label}</span><span class="stat-icon ${tint}">${I(ic,17)}</span></div><div class="stat-value">${value}</div><div class="stat-foot">${foot}</div></article>`}
function productRow(p,compact=false){return `<tr><td><div class="product-cell">${thumb(p)}<div class="product-meta"><b>${esc(p.name)}</b><span>${esc(p.code)} · ${esc(p.category)}</span></div></div></td><td class="price">${rupiah(p.price)}</td><td>${p.stock<=5?`<strong style="color:${p.stock===0?'#c34c51':'#bd812b'}">${p.stock} ${esc(p.unit||'Pcs')}</strong>`:`${p.stock} ${esc(p.unit||'Pcs')}`}</td>${compact?'':`<td>${esc(p.supplier||'—')}</td><td>${statusBadge(p)}</td>`}<td><div class="actions-cell"><button class="action-icon" data-edit-product="${esc(p.id)}" title="Ubah barang">${I('pencil',14)}</button><button class="action-icon danger" data-delete-product="${esc(p.id)}" title="Hapus barang">${I('trash',14)}</button></div></td></tr>`}
function dashboard(){const count=db.products.length;const totalValue=db.products.reduce((n,p)=>n+Number(p.price||0)*Number(p.stock||0),0);const low=lowStock().length;const totalUnits=db.products.reduce((n,p)=>n+Number(p.stock||0),0);const actions=`<button class="btn" data-action="export">${I('download',15)} Ekspor CSV</button><button class="btn btn-primary" data-action="add-product">${I('plus',15)} Tambah Barang</button>`;const latest=[...db.products].sort((a,b)=>(b.updatedAt||'').localeCompare(a.updatedAt||'')).slice(0,5);return `${pageHead('Ringkasan Inventaris','Pantau persediaan dan aktivitas barang Anda secara real-time.',actions,`DASHBOARD · ${new Intl.DateTimeFormat('id-ID',{weekday:'long',day:'numeric',month:'long',year:'numeric'}).format(new Date()).toUpperCase()}`)}<div class="stats-grid">${statCard('Total Barang',count,'<span class="up">↗ Inventaris aktif</span>','#', 'box')}${statCard('Total Unit Stok',totalUnits,'<span class="up">Semua lokasi</span>','','green')}${statCard('Nilai Persediaan',rupiahCompact(totalValue),'<span class="up">Harga modal tercatat</span>','','violet')}${statCard('Stok Menipis',low,low?'<span class="low">Perlu segera diperiksa</span>':'<span class="up">Semua stok aman</span>','','orange')}</div><div class="dashboard-grid"><section class="panel"><div class="panel-head"><div><h2 class="panel-title">Pergerakan Stok</h2><p class="panel-subtitle">Ringkasan stok barang 7 hari terakhir</p></div><div class="chart-legend"><span><i class="legend-dot"></i>Barang masuk</span><span><i class="legend-dot light"></i>Barang keluar</span></div></div><div class="chart-box">${chartSvg()}</div></section><section class="panel"><div class="panel-head"><div><h2 class="panel-title">Perlu Perhatian</h2><p class="panel-subtitle">Barang yang stoknya rendah</p></div><button class="text-link" data-page="products">Lihat semua</button></div><div class="stock-list">${low?lowStock().slice(0,4).map(p=>`<div class="stock-row">${thumb(p)}<div class="item-info"><strong>${esc(p.name)}</strong><span>${esc(p.code)} · ${esc(p.category)}</span></div><div class="stock-right"><strong>${p.stock} ${esc(p.unit||'Pcs')}</strong><span>${p.stock===0?'Stok habis':'Batas minimum'}</span></div></div>`).join(''):`<div class="empty-state">${I('check',24)}<b>Semua stok aman</b><span>Tidak ada barang yang perlu perhatian.</span></div>`}</div></section></div><div class="dashboard-grid"><section class="panel"><div class="panel-head"><div><h2 class="panel-title">Barang Terbaru</h2><p class="panel-subtitle">Pembaruan inventaris terakhir</p></div><button class="text-link" data-page="products">Lihat semua barang ${I('arrow',12)}</button></div>${latest.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>BARANG</th><th>HARGA</th><th>STOK</th><th>SUPPLIER</th><th>STATUS</th><th></th></tr></thead><tbody>${latest.map(p=>productRow(p)).join('')}</tbody></table></div>`:`<div class="empty-state">${I('box',26)}<b>Belum ada barang</b><span>Tambahkan barang pertama ke inventaris.</span></div>`}</section><section class="panel"><div class="panel-head"><div><h2 class="panel-title">Kategori Barang</h2><p class="panel-subtitle">Barang berdasarkan kategori</p></div><button class="text-link" data-page="categories">Semua kategori</button></div><div class="category-card-grid">${db.categories.slice(0,6).map((c,i)=>{const n=db.products.filter(p=>p.category===c.name).length;const icons=['laptop','keyboard','box','tag','shield','layers'];return `<div class="category-mini"><div class="category-mini-head"><span class="category-mini-icon">${I(icons[i%icons.length],14)}</span><b>${n}</b></div><p>${esc(c.name)}</p></div>`}).join('')||'<div class="no-results">Belum ada kategori</div>'}</div></section></div><section class="stock-banner"><div class="banner-icon">${I('cloud',16)}</div><div><strong>${supa?'Data inventaris Anda tersinkron':'Simpan data di cloud dengan Supabase'}</strong><span>${supa?'Perubahan akan disinkronkan ke database Supabase.':'Hubungkan database Supabase untuk mengakses data dari beberapa perangkat.'}</span></div><button class="banner-action" data-action="settings">${supa?'Kelola koneksi':'Hubungkan sekarang'} ${I('arrow',13)}</button></section>`}
function chartSvg(){const days=['Sen','Sel','Rab','Kam','Jum','Sab','Min'];const a=[40,62,49,76,57,87,70], b=[25,39,31,52,39,64,49];const pts=arr=>arr.map((y,i)=>`${50+i*91},${151-y*1.18}`).join(' ');const d=`M${pts(a).replaceAll(' ',',L')}`;return `<svg class="chart-svg" viewBox="0 0 600 170" preserveAspectRatio="none" role="img" aria-label="Grafik pergerakan stok tujuh hari"><defs><linearGradient id="area-fill" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#4387f4" stop-opacity=".16"/><stop offset="1" stop-color="#4387f4" stop-opacity="0"/></linearGradient></defs>${[31,66,101,136].map(y=>`<line class="gridline" x1="38" x2="588" y1="${y}" y2="${y}"/>`).join('')}<path class="area" d="${d} L596,154 L50,154 Z"/><polyline class="line-secondary" points="${pts(b)}"/><polyline class="line-main" points="${pts(a)}"/>${a.map((y,i)=>`<circle class="chart-point" cx="${50+i*91}" cy="${151-y*1.18}" r="3"/>`).join('')}${days.map((day,i)=>`<text x="${50+i*91}" y="168" text-anchor="middle">${day}</text>`).join('')}<text x="8" y="139">20</text><text x="8" y="104">40</text><text x="8" y="69">60</text><text x="8" y="34">80</text></svg>`}
function productPage(){const filtered=db.products.filter(p=>{const q=query.toLowerCase();const matches=!q||[p.name,p.code,p.category,p.supplier].join(' ').toLowerCase().includes(q);const f=productFilter==='Semua'||(productFilter==='Menipis'&&p.stock>0&&p.stock<=5)||(productFilter==='Habis'&&p.stock===0)||(productFilter==='Tersedia'&&p.stock>5);return matches&&f}).sort((a,b)=>a.name.localeCompare(b.name));const actions=`<button class="btn" data-action="export">${I('download',15)} Ekspor</button><button class="btn btn-primary" data-action="add-product">${I('plus',15)} Tambah Barang</button>`;return `${pageHead('Daftar Barang','Kelola semua produk dan pantau ketersediaan stok.',actions)}<section class="panel"><div class="panel-head"><div><h2 class="panel-title">Semua Barang <span style="color:#94a1b2;font:500 10px 'DM Sans'">(${filtered.length})</span></h2><p class="panel-subtitle">Data barang inventaris Anda</p></div></div><div class="table-toolbar"><label class="field-search">${I('search',14)}<input id="product-search" placeholder="Cari nama barang atau kode..." value="${esc(query)}"></label><select class="select-control" id="stock-filter" aria-label="Filter kondisi stok">${['Semua','Tersedia','Menipis','Habis'].map(s=>`<option ${s===productFilter?'selected':''}>${s}</option>`).join('')}</select><button class="btn btn-sm" data-action="export">${I('download',13)} Unduh CSV</button></div>${filtered.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>BARANG</th><th>HARGA</th><th>STOK</th><th>SUPPLIER</th><th>STATUS</th><th style="text-align:right">AKSI</th></tr></thead><tbody>${filtered.map(p=>productRow(p)).join('')}</tbody></table></div><div class="table-pagination"><span>Menampilkan ${filtered.length} dari ${db.products.length} barang</span><div class="pagination-buttons"><button class="page-no">1</button></div></div>`:`<div class="empty-state">${I(query?'search':'box',28)}<b>${query?'Barang tidak ditemukan':'Belum ada barang'}</b><span>${query?'Ubah kata kunci pencarian atau filter stok.':'Mulai tambahkan barang ke inventaris Anda.'}</span>${query?'':`<br><button class="btn btn-primary btn-sm" style="margin-top:13px" data-action="add-product">${I('plus',13)} Tambah Barang</button>`}</div>`}</section>`}
function categoriesPage(){const rows=db.categories.map(c=>{const n=db.products.filter(p=>p.category===c.name).length;return `<tr><td><div class="product-cell"><div class="item-thumb purple">${I('layers',17)}</div><div class="product-meta"><b>${esc(c.name)}</b><span>${esc(c.description||'Kategori barang')}</span></div></div></td><td>${n} barang</td><td><span class="status status-neutral">Aktif</span></td><td><div class="actions-cell"><button class="action-icon" data-edit-category="${esc(c.id)}" title="Ubah kategori">${I('pencil',14)}</button><button class="action-icon danger" data-delete-category="${esc(c.id)}" title="Hapus kategori">${I('trash',14)}</button></div></td></tr>`}).join('');return `${pageHead('Kategori','Atur klasifikasi barang agar data inventaris tetap terorganisir.',`<button class="btn btn-primary" data-action="add-category">${I('plus',15)} Tambah Kategori</button>`)}<section class="panel"><div class="panel-head"><div><h2 class="panel-title">Semua Kategori <span style="color:#94a1b2;font:500 10px 'DM Sans'">(${db.categories.length})</span></h2><p class="panel-subtitle">Kategori yang tersedia di inventaris</p></div></div>${rows?`<div class="table-wrap"><table class="data-table"><thead><tr><th>NAMA KATEGORI</th><th>JUMLAH BARANG</th><th>STATUS</th><th style="text-align:right">AKSI</th></tr></thead><tbody>${rows}</tbody></table></div>`:`<div class="empty-state">${I('layers',28)}<b>Belum ada kategori</b><span>Buat kategori untuk mengelompokkan barang.</span></div>`}</section>`}
function suppliersPage(){const rows=db.suppliers.map(s=>{const n=db.products.filter(p=>p.supplier===s.name).length;return `<tr><td><div class="product-cell"><div class="item-thumb cyan">${I('truck',17)}</div><div class="product-meta"><b>${esc(s.name)}</b><span>${esc(s.address||'—')}</span></div></div></td><td>${esc(s.contact||'—')}</td><td>${esc(s.email||'—')}</td><td>${n} barang</td><td><div class="actions-cell"><button class="action-icon" data-edit-supplier="${esc(s.id)}" title="Ubah supplier">${I('pencil',14)}</button><button class="action-icon danger" data-delete-supplier="${esc(s.id)}" title="Hapus supplier">${I('trash',14)}</button></div></td></tr>`}).join('');return `${pageHead('Supplier','Kelola informasi pemasok barang inventaris Anda.',`<button class="btn btn-primary" data-action="add-supplier">${I('plus',15)} Tambah Supplier</button>`)}<section class="panel"><div class="panel-head"><div><h2 class="panel-title">Daftar Supplier <span style="color:#94a1b2;font:500 10px 'DM Sans'">(${db.suppliers.length})</span></h2><p class="panel-subtitle">Informasi mitra pemasok barang</p></div></div>${rows?`<div class="table-wrap"><table class="data-table"><thead><tr><th>NAMA SUPPLIER</th><th>TELEPON</th><th>EMAIL</th><th>PRODUK</th><th style="text-align:right">AKSI</th></tr></thead><tbody>${rows}</tbody></table></div>`:`<div class="empty-state">${I('truck',28)}<b>Belum ada supplier</b><span>Tambahkan pemasok untuk data yang lebih lengkap.</span></div>`}</section>`}
function settingsPage(){return `${pageHead('Pengaturan','Atur koneksi data dan preferensi aplikasi.')}<div class="dashboard-grid"><section class="panel"><div class="panel-head"><div><h2 class="panel-title">Koneksi Database</h2><p class="panel-subtitle">Pilih tempat penyimpanan data inventaris Anda</p></div></div><div style="padding:0 17px 17px"><div class="settings-intro"><div class="settings-intro-icon">${I('cloud',19)}</div><div><strong>Sinkronkan dengan Supabase</strong><p>Hubungkan proyek Supabase untuk menyimpan data online dan membukanya dari perangkat lain. Koneksi ini memakai REST API dan hanya memerlukan URL proyek serta public anon key.</p></div></div><div class="settings-line"><div><b>Status koneksi</b><span>${supa?'Terhubung ke database Supabase':'Data tersimpan di browser ini saja'}</span></div><div class="connection-row">${connectionLabel()}</div></div><div class="settings-line"><div><b>Barang tersimpan</b><span>${db.products.length} barang inventaris</span></div><span style="font-size:10px;color:#51647f">${db.categories.length} kategori · ${db.suppliers.length} supplier</span></div><div style="display:flex;gap:8px;margin-top:14px;flex-wrap:wrap"><button class="btn btn-primary" data-action="supabase">${I(supa?'settings':'plus',14)} ${supa?'Ubah koneksi':'Hubungkan Supabase'}</button>${supa?`<button class="btn" data-action="sync">${I('arrow',14)} Sinkronkan ulang</button><button class="btn btn-danger" data-action="disconnect">Putuskan koneksi</button>`:''}</div></div></section><section class="panel"><div class="panel-head"><div><h2 class="panel-title">Penyimpanan Lokal</h2><p class="panel-subtitle">Data di perangkat browser saat ini</p></div></div><div style="padding:0 17px 17px"><div class="settings-line"><div><b>Penyimpanan otomatis</b><span>Perubahan disimpan otomatis pada browser ini.</span></div><span class="status status-ok"><i class="status-dot"></i>Aktif</span></div><div class="settings-line"><div><b>Unduh salinan data</b><span>Ekspor barang inventaris ke berkas CSV.</span></div><button class="btn btn-sm" data-action="export">${I('download',13)} Ekspor</button></div><div class="settings-line"><div><b>Data contoh</b><span>Muat ulang data demo pada perangkat ini.</span></div><button class="btn btn-sm" data-action="reset-demo">Pulihkan demo</button></div><div class="danger-note" style="margin-top:13px">Untuk data multi-pengguna, Anda perlu menyiapkan tabel dan kebijakan keamanan (RLS) di proyek Supabase sendiri. Jangan pernah memasukkan service_role key pada aplikasi browser.</div></div></section></div><section class="panel" style="margin-top:16px"><div class="panel-head"><div><h2 class="panel-title">Tentang ZAVEN</h2><p class="panel-subtitle">Smart Inventory · versi 1.0</p></div></div><div style="padding:0 17px 17px;display:flex;align-items:center;gap:12px"><div class="brand-mark" style="width:37px;height:37px;border-radius:11px">${I('spark',18)}</div><div><b style="font:700 11px 'Manrope'">Kelola stok, lebih mudah</b><div style="font-size:9px;color:#8e9aab;margin-top:4px">Aplikasi inventaris sederhana, praktis, dan siap digunakan secara offline.</div></div></div></section>`}
const groupMembers=[{name:'Nirwa Feinurjn',number:4},{name:'Nurul Iftita Nevinda',number:5},{name:'Oktivianda',number:7},{name:'Raffa Brillian Putra Widianto',number:15},{name:'Rahmatullah Sastra Ardiansyah',number:17},{name:'Rick Valentino Wenas',number:22},{name:'Selfi Herdiyah Anggreini',number:25},{name:'Siti Laraswati',number:29}];
function groupProfileModal(){const body=`<div class="team-intro"><span class="team-icon">${I('user',19)}</span><div><strong>Nama Kelompok</strong><span>Anggota tim ZAVEN Smart Inventory</span></div><b class="team-total">${groupMembers.length} anggota</b></div><div class="team-member-list">${groupMembers.map(m=>`<div class="team-member"><span class="team-member-avatar">${esc(initials(m.name))}</span><span class="team-member-name">${esc(m.name)}</span><span class="team-member-number">${m.number}</span></div>`).join('')}</div>`;modal('Anggota Kelompok','Daftar nama anggota kelompok.',body,`<button class="btn btn-primary" data-action="close-modal">Selesai</button>`,true)}
function profilePage(){const user=currentUserName();return `${pageHead('Profil','Informasi profil administrator aplikasi.')}<div class="dashboard-grid"><section class="panel"><div class="panel-head"><div><h2 class="panel-title">Informasi Akun</h2><p class="panel-subtitle">Profil yang ditampilkan pada aplikasi</p></div><button class="btn btn-sm" data-action="edit-profile">${I('pencil',13)} Ubah profil</button></div><div style="padding:0 17px 18px"><div class="profile-card"><div class="avatar">${esc(initials(user))}</div><div><strong>${esc(user)}</strong><span>${authToken?'Pengguna Supabase · Akun aktif':'Administrator · Demo lokal'}</span></div></div><div style="margin-top:15px">${[['user','Nama lengkap',user],['info','Peran',authToken?'Pengguna':'Administrator'],['cloud','Penyimpanan',supa?'Supabase':'Browser lokal']].map(([ic,k,v])=>`<div class="settings-line"><div style="display:flex;align-items:center;gap:9px;color:#8291a6">${I(ic,15)}<b style="font-size:10px;color:#718098">${k}</b></div><span style="font-size:10px;color:#445773">${esc(v)}</span></div>`).join('')}</div></div></section><section class="panel"><div class="panel-head"><div><h2 class="panel-title">Preferensi Aplikasi</h2><p class="panel-subtitle">Tampilan dan kenyamanan penggunaan</p></div></div><div style="padding:0 17px 17px"><div class="settings-line"><div><b>Notifikasi stok menipis</b><span>Tampilkan pengingat ketika stok ≤ 5 unit.</span></div><input class="switch" type="checkbox" checked id="low-notify"></div><div class="settings-line"><div><b>Mode offline</b><span>Aplikasi dapat dibuka saat tanpa internet.</span></div><span class="status status-ok"><i class="status-dot"></i>Siap</span></div><button class="btn btn-danger" style="margin-top:15px" data-action="logout">${I('logout',14)} Keluar</button></div></section></div>`}
function logoMark(){return `<div class="brand-mark"><svg viewBox="0 0 32 32" fill="none"><path d="M8 7h17L8 25h17" stroke="white" stroke-width="4.5" stroke-linecap="square" stroke-linejoin="round"/><path d="M22.2 25 26 20.9" stroke="#9fd8ff" stroke-width="3.3" stroke-linecap="round"/></svg></div>`}
function splash(){return `<main class="splash-screen"><div class="splash-orb orb-one"></div><div class="splash-orb orb-two"></div><div class="splash-content">${logoMark()}<div class="splash-brand">ZAVEN</div><div class="splash-sub">Smart Inventory</div><div class="splash-loader" role="status" aria-label="Memuat aplikasi"><i></i><i></i><i></i></div><div class="splash-caption">Menyiapkan ruang inventaris Anda…</div></div><div class="splash-footer">SIMPLE&nbsp; · &nbsp;FAST&nbsp; · &nbsp;RELIABLE</div></main>`}
function loginPage(){const lastEmail=localStorage.getItem('zaven-last-email')||'smk1krian@sch.id';return `<main class="login-screen"><div class="login-ambient ambient-a"></div><div class="login-ambient ambient-b"></div><section class="login-layout"><aside class="login-brand-panel"><div class="login-brand-top">${logoMark()}<div><b>ZAVEN</b><span>SMART INVENTORY</span></div></div><div class="login-brand-copy"><span class="login-overline">INVENTARIS YANG LEBIH RAPI</span><h1>Semua stok.<br><em>Satu kendali.</em></h1><p>Pantau barang, kategori, dan supplier Anda dalam satu ruang kerja yang mudah digunakan.</p><div class="login-feature-list"><div>${I('box',16)}<span>Kelola barang & pantau stok</span></div><div>${I('chart',16)}<span>Ringkasan inventaris dalam sekejap</span></div><div>${I('cloud',16)}<span>Data lokal atau tersinkron ke Supabase</span></div></div></div><div class="login-brand-bottom"><span class="brand-mark-small">${I('shield',14)}</span><span>Data Anda tersimpan aman sesuai pengaturan penyimpanan.</span></div></aside><section class="login-form-panel"><div class="login-card"><div class="login-mobile-brand">${logoMark()}<div><b>ZAVEN</b><span>Smart Inventory</span></div></div><div class="login-welcome"><div class="login-step">SELAMAT DATANG KEMBALI</div><h2>Masuk ke akun Anda</h2><p>Gunakan email dan kata sandi untuk melanjutkan.</p></div><form id="login-form" class="login-form"><label class="login-field"><span>Email</span><div class="login-input-wrap">${I('user',16)}<input type="email" id="login-email" value="${esc(lastEmail)}" autocomplete="username" placeholder="nama@email.com" required></div></label><label class="login-field"><span>Kata sandi</span><div class="login-input-wrap">${I('shield',16)}<input type="password" id="login-password" autocomplete="current-password" placeholder="Masukkan kata sandi" required minlength="6"><button type="button" class="password-toggle" data-action="toggle-password" aria-label="Tampilkan kata sandi">Tampilkan</button></div></label><div class="login-options"><label class="remember-option"><input type="checkbox" id="remember-login" checked><span>Ingat email di perangkat ini</span></label><button class="text-link" type="button" data-action="forgot-password">Lupa kata sandi?</button></div><div class="login-error" id="login-error" role="alert"></div><button class="btn btn-primary login-submit" type="submit">${busy?'<span class="button-spinner"></span> Memeriksa…':`Masuk ${I('arrow',15)}`}</button></form><div class="login-divider"><span></span>atau<span></span></div><button class="btn demo-button" data-action="demo-entry">${I('grid',15)} Masuk dengan data demo lokal</button>${installButtonMarkup('login')}<div class="login-setup"><span>${supa?`Database cloud siap · ${esc(supa.url.replace(/^https:\/\//,'').split('.')[0])}`:'Belum menyiapkan database cloud?'}</span><button data-action="setup-from-login">${supa?'Pengaturan koneksi':'Hubungkan Supabase'}</button></div><p class="login-legal">Mode demo menyimpan data hanya di browser ini. Login cloud menggunakan autentikasi Supabase Anda.</p></div><div class="login-copyright">© ${new Date().getFullYear()} ZAVEN Smart Inventory</div></section></section></main><div id="modal-root"></div><div class="toast-stack" id="toast-stack"></div>`}
function render(){if(!splashComplete){$('#app').innerHTML=splash();return}if(!hasAppSession()){$('#app').innerHTML=loginPage();return}const pages={overview:dashboard,products:productPage,categories:categoriesPage,suppliers:suppliersPage,settings:settingsPage,profile:profilePage};$('#app').innerHTML=shell((pages[activePage]||dashboard)());}
async function loginWithSupabase(){const form=$('#login-form');if(!form?.reportValidity())return;if(!supa){const error=$('#login-error');if(error)error.textContent='Hubungkan proyek Supabase terlebih dahulu, atau gunakan mode demo lokal.';return}const email=$('#login-email')?.value?.trim()||'';const password=$('#login-password')?.value||'';if($('#remember-login')?.checked)localStorage.setItem('zaven-last-email',email);busy=true;render();try{const endpoint=`${supa.url}/auth/v1/token?grant_type=password`;const response=await fetch(endpoint,{method:'POST',headers:{apikey:supa.key,'Content-Type':'application/json'},body:JSON.stringify({email,password})});const result=await response.json();if(!response.ok)throw new Error(result.msg||result.message||result.error_description||'Email atau kata sandi tidak valid.');authToken=result.access_token;authUser=result.user;sessionStorage.setItem('zaven-access-token',authToken);sessionStorage.setItem('zaven-auth-user',JSON.stringify(authUser));sessionStorage.setItem('zaven-session','cloud');busy=false;await syncFromRemote();render();toast('Berhasil masuk. Data Supabase sudah dimuat.')}catch(error){busy=false;render();const el=$('#login-error');if(el)el.textContent=error.message||'Gagal masuk. Periksa koneksi dan akun Supabase Anda.';else toast('Gagal masuk. Periksa koneksi dan akun Anda.')}}
function toast(msg,type='auto'){const root=$('#toast-stack');if(!root)return;const kind=type==='auto'?(/gagal|error|tidak valid|wajib|sudah (digunakan|ada)|tidak tersedia|tidak dapat/i.test(msg)?'error':'success'):type;const t=document.createElement('div');t.className=`toast toast-${kind}`;t.setAttribute('role',kind==='error'?'alert':'status');t.setAttribute('aria-live',kind==='error'?'assertive':'polite');t.innerHTML=`${I(kind==='error'?'info':'check',15)}<span>${esc(msg)}</span>`;root.append(t);setTimeout(()=>t.remove(),3600)}
function modal(title,subtitle,body,footer='',wide=false){activeModal=true;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><header class="modal-head"><div><h2>${esc(title)}</h2><p>${esc(subtitle)}</p></div><button class="modal-close" data-action="close-modal" aria-label="Tutup">${I('close',15)}</button></header><div class="modal-body">${body}</div>${footer?`<footer class="modal-footer">${footer}</footer>`:''}</section></div>`;$('.modal-backdrop').addEventListener('click',e=>{if(e.target.classList.contains('modal-backdrop'))closeModal()});const saveButton=$('.modal-footer [data-submit]');saveButton?.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();const kind=saveButton.dataset.submit;if(kind==='product')saveProduct($('#product-form')?.dataset.editId||null);if(kind==='category')saveCategory($('#category-form')?.dataset.editId||null);if(kind==='supplier')saveSupplier($('#supplier-form')?.dataset.editId||null);if(kind==='profile')$('#profile-form')?.requestSubmit()});setTimeout(()=>$('.modal input, .modal select, .modal textarea')?.focus(),70)}
function closeModal(){activeModal=null;const r=$('#modal-root');if(r)r.innerHTML=''}
function field(label,id,value='',type='text',opts={}){const full=opts.full?' full':'';const required=opts.required===false?'':' required';const placeholder=opts.placeholder||'';let input=type==='select'?`<select id="${id}"${required}>${(opts.options||[]).map(o=>`<option value="${esc(o)}" ${String(o)===String(value)?'selected':''}>${esc(o||'Pilih…')}</option>`).join('')}</select>`:type==='textarea'?`<textarea id="${id}" placeholder="${esc(placeholder)}"${required}>${esc(value)}</textarea>`:`<input id="${id}" type="${type}" value="${esc(value)}" placeholder="${esc(placeholder)}"${required} ${type==='number'?'min="0"':''}>`;return `<div class="form-field${full}"><label for="${id}">${esc(label)}${opts.required===false?'':' *'}</label>${input}${opts.help?`<span class="help-text">${esc(opts.help)}</span>`:''}</div>`}
async function compressProductImage(file){if(!file||!file.type.startsWith('image/'))throw new Error('Pilih file gambar yang valid.');if(file.size>12*1024*1024)throw new Error('Ukuran foto maksimal 12 MB sebelum dikompres.');const bitmap=await createImageBitmap(file);const ratio=Math.min(1,1200/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*ratio));canvas.height=Math.max(1,Math.round(bitmap.height*ratio));const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close?.();return canvas.toDataURL('image/jpeg',.76)}
function refreshProductImagePreview(){const box=$('#product-image-preview'),clear=$('#clear-product-image'),label=$('#image-upload-label');if(!box)return;if(pendingProductImage){box.innerHTML=`<img src="${esc(pendingProductImage)}" alt="Pratinjau foto barang">`;if(label)label.textContent='Foto siap disimpan pada kolom gambar.';if(clear)clear.hidden=false}else{box.innerHTML=`<span class="image-upload-empty">${I('image',25)}<b>Belum ada foto</b><small>JPG, PNG, WEBP — foto akan dikompres otomatis</small></span>`;if(label)label.textContent='Pilih gambar produk dari perangkat Anda.';if(clear)clear.hidden=true}}
async function onProductImageSelected(file){try{toast('Foto sedang diproses…');pendingProductImage=await compressProductImage(file);refreshProductImagePreview();toast('Foto siap disimpan ke kolom gambar.','success')}catch(e){toast(e.message||'Foto tidak dapat diproses.','error')}finally{const input=$('#f-image');if(input)input.value=''}}
function productModal(id=null){const p=id?db.products.find(x=>String(x.id)===String(id)):null;pendingProductImage=p?.image||'';const body=`<form id="product-form" class="form-grid" data-edit-id="${esc(id||'')}">${field('Kode barang','f-code',p?.code||'','text',{placeholder:'Contoh: K010'})}${field('Nama barang','f-name',p?.name||'','text',{placeholder:'Masukkan nama barang'})}${field('Kategori','f-category',p?.category||db.categories[0]?.name||'','select',{options:db.categories.map(c=>c.name)})}${field('Harga (Rp)','f-price',p?.price??'','number',{placeholder:'0'})}${field('Jumlah stok','f-stock',p?.stock??'','number',{placeholder:'0'})}${field('Satuan','f-unit',p?.unit||'Pcs','select',{options:['Pcs','Unit','Box','Pack','Lusin','Kg','Meter']})}${field('Supplier','f-supplier',p?.supplier||db.suppliers[0]?.name||'','select',{options:['',...db.suppliers.map(s=>s.name)],required:false})}<div class="form-field full"><label for="f-image">Foto barang <span class="optional-label">(opsional)</span></label><div class="image-upload-card"><input id="f-image" type="file" accept="image/*" hidden><div class="image-upload-preview" id="product-image-preview"></div><div class="image-upload-copy"><strong>Foto produk</strong><span id="image-upload-label">Pilih gambar produk dari perangkat Anda.</span><div class="image-upload-actions"><button type="button" class="btn btn-sm btn-primary" data-action="pick-image">${I('image',13)} Pilih gambar</button><button type="button" class="btn btn-sm" id="clear-product-image" data-action="clear-image" hidden>Hapus foto</button></div></div></div><span class="help-text">Gambar dikompres lalu disimpan sebagai data pada kolom <b>gambar</b> di tabel items.</span></div>${field('Catatan','f-notes',p?.notes||'','textarea',{full:true,required:false,placeholder:'Deskripsi atau catatan tambahan'})}</form>`;modal(p?'Ubah Barang':'Tambah Barang',p?'Perbarui informasi barang di inventaris.':'Lengkapi informasi barang baru.',body,`<button class="btn" data-action="close-modal">Batal</button><button class="btn btn-primary" data-submit="product">${I('check',14)} ${p?'Simpan Perubahan':'Simpan Barang'}</button>`);refreshProductImagePreview();$('#product-form').addEventListener('submit',e=>{e.preventDefault();saveProduct(id)})}
async function saveProduct(id){const form=$('#product-form');if(!form.reportValidity())return;const name=$('#f-name').value.trim(),code=$('#f-code').value.trim();if(db.products.some(p=>p.code.toLowerCase()===code.toLowerCase()&&String(p.id)!==String(id))){toast('Kode barang sudah digunakan.');$('#f-code').focus();return}const before=structuredClone(db.products),old=db.products.find(p=>String(p.id)===String(id));const rec={id:id||`p-${crypto.randomUUID?.()||Date.now()}`,code,name,category:$('#f-category').value,price:Number($('#f-price').value),stock:Number($('#f-stock').value),unit:$('#f-unit').value,supplier:$('#f-supplier').value,notes:$('#f-notes').value.trim(),image:pendingProductImage,updatedAt:todayISO(),icon:/mouse/i.test(name)?'mouse':/keyboard/i.test(name)?'keyboard':/printer/i.test(name)?'printer':/laptop|komputer|monitor/i.test(name)?'laptop':'box'};if(id)db.products=db.products.map(p=>String(p.id)===String(id)?rec:p);else db.products.unshift(rec);saveData();closeModal();render();const result=await persistRemote('products',rec,id?'update':'insert');if(!result.ok){db.products=before;saveData();render();notifyPersist(result,'Perubahan barang dibatalkan; data cloud tidak berubah.');return}notifyPersist(result,id?`Barang "${name}" berhasil diperbarui.`:`Barang "${name}" berhasil ditambahkan.`)}
function categoryModal(id=null){const c=id?db.categories.find(x=>x.id===id):null;modal(c?'Ubah Kategori':'Tambah Kategori',c?'Perbarui detail kategori.':'Buat pengelompokan baru untuk barang.',`<form id="category-form" class="form-grid" data-edit-id="${esc(id||'')}">${field('Nama kategori','f-cat-name',c?.name||'','text',{full:true,placeholder:'Contoh: Peralatan Kantor'})}${field('Deskripsi','f-cat-desc',c?.description||'','textarea',{full:true,required:false,placeholder:'Deskripsi singkat kategori'})}</form>`,`<button class="btn" data-action="close-modal">Batal</button><button class="btn btn-primary" data-submit="category">${I('check',14)} Simpan</button>`);$('#category-form').addEventListener('submit',e=>{e.preventDefault();saveCategory(id)})}
async function saveCategory(id){const form=$('#category-form');if(!form.reportValidity())return;const name=$('#f-cat-name').value.trim();if(db.categories.some(c=>c.name.toLowerCase()===name.toLowerCase()&&String(c.id)!==String(id))){toast('Nama kategori sudah ada.');return}const beforeCategories=structuredClone(db.categories),beforeProducts=structuredClone(db.products),oldName=id?db.categories.find(c=>String(c.id)===String(id))?.name:null;const rec={id:id||`c-${Date.now()}`,name,description:$('#f-cat-desc').value.trim()};if(id){db.categories=db.categories.map(c=>String(c.id)===String(id)?rec:c);db.products=db.products.map(p=>p.category===oldName?{...p,category:name,updatedAt:todayISO()}:p)}else db.categories.push(rec);saveData();closeModal();render();const affected=id?db.products.filter(p=>p.category===name):[];const results=await Promise.all(affected.map(p=>persistRemote('products',p,'update')));const failure=results.find(r=>!r.ok);if(failure){db.categories=beforeCategories;db.products=beforeProducts;saveData();render();notifyPersist(failure,'Perubahan kategori dibatalkan; data cloud tidak berubah.');return}notifyPersist({ok:true,local:!supa||!supa.productsTable},id?`Kategori "${name}" berhasil diperbarui.`:`Kategori "${name}" berhasil ditambahkan.`)}
function supplierModal(id=null){const s=id?db.suppliers.find(x=>x.id===id):null;modal(s?'Ubah Supplier':'Tambah Supplier',s?'Perbarui informasi pemasok.':'Lengkapi data pemasok barang.',`<form id="supplier-form" class="form-grid" data-edit-id="${esc(id||'')}">${field('Nama supplier','f-sup-name',s?.name||'','text',{full:true,placeholder:'Contoh: PT. Indonesia Jaya'})}${field('Nomor telepon','f-sup-phone',s?.contact||'','tel',{placeholder:'021 555 0101',required:false})}${field('Email','f-sup-email',s?.email||'','email',{placeholder:'sales@email.co.id',required:false})}${field('Alamat','f-sup-address',s?.address||'','text',{full:true,placeholder:'Kota atau alamat supplier',required:false})}</form>`,`<button class="btn" data-action="close-modal">Batal</button><button class="btn btn-primary" data-submit="supplier">${I('check',14)} Simpan</button>`);$('#supplier-form').addEventListener('submit',e=>{e.preventDefault();saveSupplier(id)})}
async function saveSupplier(id){const form=$('#supplier-form');if(!form.reportValidity())return;const name=$('#f-sup-name').value.trim();if(db.suppliers.some(x=>x.name.toLowerCase()===name.toLowerCase()&&String(x.id)!==String(id))){toast('Nama supplier sudah ada.');return}const beforeSuppliers=structuredClone(db.suppliers),beforeProducts=structuredClone(db.products),oldName=id?db.suppliers.find(x=>String(x.id)===String(id))?.name:null;const rec={id:id||`s-${Date.now()}`,name,contact:$('#f-sup-phone').value.trim(),email:$('#f-sup-email').value.trim(),address:$('#f-sup-address').value.trim()};if(id){db.suppliers=db.suppliers.map(x=>String(x.id)===String(id)?rec:x);db.products=db.products.map(p=>p.supplier===oldName?{...p,supplier:name,updatedAt:todayISO()}:p)}else db.suppliers.push(rec);saveData();closeModal();render();const affected=id?db.products.filter(p=>p.supplier===name):[];const results=await Promise.all(affected.map(p=>persistRemote('products',p,'update')));const failure=results.find(r=>!r.ok);if(failure){db.suppliers=beforeSuppliers;db.products=beforeProducts;saveData();render();notifyPersist(failure,'Perubahan supplier dibatalkan; data cloud tidak berubah.');return}notifyPersist({ok:true,local:!supa||!supa.productsTable},id?`Supplier "${name}" berhasil diperbarui.`:`Supplier "${name}" berhasil ditambahkan.`)}
function confirmDelete(kind,id){const key={product:'products',category:'categories',supplier:'suppliers'}[kind],rec=db[key].find(x=>String(x.id)===String(id));if(!rec)return;const name=rec.name||rec.code,linked=kind==='category'?db.products.filter(p=>p.category===name).length:kind==='supplier'?db.products.filter(p=>p.supplier===name).length:0;const warning=linked?`<div class="danger-note">${linked} barang terkait. Saat menghapus, relasi ${kind==='category'?'kategori':'supplier'} pada barang tersebut akan dikosongkan.</div>`:`<div class="danger-note">Hapus <b>${esc(name)}</b>? Tindakan ini tidak dapat dibatalkan.</div>`;modal(`Hapus ${kind==='product'?'Barang':kind==='category'?'Kategori':'Supplier'}?`,'Periksa data sebelum melanjutkan.',warning,`<button class="btn" data-action="close-modal">Batal</button><button class="btn btn-danger" data-confirm-delete="${kind}:${esc(id)}">${I('trash',14)} Hapus</button>`)}
async function deleteRec(kind,id){const key={product:'products',category:'categories',supplier:'suppliers'}[kind],rec=db[key].find(x=>String(x.id)===String(id));if(!rec)return;const label={product:'Barang',category:'Kategori',supplier:'Supplier'}[kind],name=rec.name||rec.code,beforeList=structuredClone(db[key]),beforeProducts=structuredClone(db.products);let affected=[];if(kind==='category')affected=db.products.filter(p=>p.category===name).map(p=>({...p,category:'',updatedAt:todayISO()}));if(kind==='supplier')affected=db.products.filter(p=>p.supplier===name).map(p=>({...p,supplier:'',updatedAt:todayISO()}));if(affected.length){const changed=new Map(affected.map(p=>[String(p.id),p]));db.products=db.products.map(p=>changed.get(String(p.id))||p)}db[key]=db[key].filter(x=>String(x.id)!==String(id));saveData();closeModal();render();const results=kind==='product'?[await persistRemote('products',rec,'delete')]:await Promise.all(affected.map(p=>persistRemote('products',p,'update')));const failure=results.find(r=>!r.ok);if(failure){db[key]=beforeList;db.products=beforeProducts;saveData();render();notifyPersist(failure,'Penghapusan dibatalkan; data cloud tidak berubah.');return}toast(`${label} "${name}" berhasil dihapus.`+(affected.length?' Barang terkait turut diperbarui.':''),'success')}
const SQL_SETUP=`-- Contoh struktur yang diharapkan oleh aplikasi ZAVEN.
-- Cocokkan kolom dengan tabel public.items Anda sebelum menjalankan.
create table if not exists public.items (
  id bigint generated by default as identity primary key,
  user_id uuid not null references auth.users(id) on delete cascade,
  code text not null,
  name text not null,
  category text,
  price numeric not null default 0,
  stock integer not null default 0,
  unit text not null default 'Pcs',
  supplier text,
  notes text,
  updated_at timestamptz not null default now(),
  unique(user_id, code)
);
alter table public.items enable row level security;
create policy \"owner manages items\" on public.items for all to authenticated using (auth.uid() = user_id) with check (auth.uid() = user_id);
-- Buat akun dari Authentication > Users sebelum login.`;
function supabaseModal(){const cfg=supa||{};const body=`<div class="settings-stack supabase-setup"><div class="supabase-hero"><span class="supabase-hero-icon">${I('cloud',20)}</span><div><strong>Hubungkan ke Supabase</strong><p>Login memakai Supabase Auth. Data barang disimpan ke tabel <b>items</b>.</p></div><span class="connection-pill ${supa?'connected':'disconnected'}">${supa?'Tersimpan':'Belum terhubung'}</span></div><form id="supa-form" class="form-grid supabase-form">${field('Project URL','f-supa-url',cfg.url||'','url',{full:true,placeholder:'https://nama-proyek.supabase.co',help:'Supabase → Project Settings → API → Project URL'})}${field('Publishable / anon key','f-supa-key',cfg.key||'','text',{full:true,placeholder:'sb_publishable_… atau anon key',help:'Gunakan kunci publik saja; jangan tempel sb_secret atau service_role.'})}${field('Tabel barang','f-table-products',cfg.productsTable||'items','text',{full:true,placeholder:'items',help:'Nama tabel inventaris pada schema public.'})}<details class="supabase-optional"><summary>Pengaturan opsional kategori & supplier</summary><p>Kosongkan bila kategori dan supplier disimpan di browser ini saja.</p>${field('Tabel kategori','f-table-categories',cfg.categoriesTable||'','text',{full:true,placeholder:'(kosong — lokal)'})}${field('Tabel supplier','f-table-suppliers',cfg.suppliersTable||'','text',{full:true,placeholder:'(kosong — lokal)'})}</details></form><div class="supabase-safe-note"><b>Catatan keamanan</b><span>Pastikan pengguna masuk melalui Supabase Auth dan RLS mengizinkan pengguna mengelola baris miliknya. Key rahasia tidak boleh dipasang di website.</span></div></div>`;modal('Koneksi Supabase','Atur database inventaris Anda.',body,`<button class="btn" data-action="close-modal">Batal</button><button class="btn btn-primary" data-action="connect-supabase">${I('cloud',14)} Uji koneksi</button>`,true);$('#supa-form').addEventListener('submit',e=>{e.preventDefault();connectSupabase()})}
async function connectSupabase(){const form=$('#supa-form');if(!form.reportValidity())return;const url=$('#f-supa-url').value.trim().replace(/\/+$/,'');if(!/^https:\/\/[\w.-]+\.supabase\.co$/i.test(url)){toast('Masukkan Project URL Supabase yang valid.');return}const key=$('#f-supa-key').value.trim();if(!key){toast('Publishable / anon key wajib diisi.');return}if(/^sb_secret_/i.test(key)||/service_role/i.test(key)){toast('Key rahasia tidak boleh dipakai di website. Gunakan publishable key.','error');return}const cfg={url,key,productsTable:$('#f-table-products').value.trim()||'items',categoriesTable:$('#f-table-categories').value.trim(),suppliersTable:$('#f-table-suppliers').value.trim()};const btn=$('[data-action="connect-supabase"]');btn.disabled=true;btn.textContent='Menguji koneksi…';try{const response=await fetch(`${url}/auth/v1/settings`,{headers:{apikey:key}});if(!response.ok)throw new Error(`Supabase menolak URL atau publishable key (${response.status}).`);supa=cfg;localStorage.setItem(CONFIG,JSON.stringify(cfg));closeModal();render();if(authToken){await syncFromRemote();render();toast(`Terhubung ke ${cfg.productsTable}; data barang berhasil dimuat.`,'success')}else toast('Koneksi tersimpan. Silakan masuk menggunakan akun Supabase Auth.','success')}catch(err){if(btn.isConnected){btn.disabled=false;btn.textContent='Uji koneksi'}toast(err.message||'Koneksi gagal. Periksa URL dan key.','error')}}
const ITEM_COLUMN_ALIASES={id:['id'],user_id:['user_id'],code:['code','kode','item_code','sku'],name:['name','nama','item_name','product_name'],category:['category','kategori','category_name'],price:['price','harga','sell_price','unit_price'],stock:['stock','stok','quantity','qty','jumlah'],unit:['unit','satuan'],supplier:['supplier','supplier_name','pemasok'],image:['image','image_url','gambar','photo','foto'],notes:['notes','description','deskripsi','keterangan'],created_at:['created_at'],updated_at:['updated_at','updatedAt','updated_on']};
async function discoverItemsColumns(){const headers={apikey:supa.key,Authorization:`Bearer ${authToken||supa.key}`};const candidates=[...new Set(Object.values(ITEM_COLUMN_ALIASES).flat())];const checks=await Promise.all(candidates.map(async col=>{try{const r=await fetch(`${supa.url}/rest/v1/${encodeURIComponent(supa.productsTable)}?select=${encodeURIComponent(col)}&limit=0`,{headers});return [col,r.ok]}catch{return [col,false]}}));itemsRemoteColumns=new Set(checks.filter(x=>x[1]).map(x=>x[0]));if(!ITEM_COLUMN_ALIASES.code.some(c=>itemsRemoteColumns.has(c))||!ITEM_COLUMN_ALIASES.name.some(c=>itemsRemoteColumns.has(c)))throw new Error('Kolom kode/kode barang dan nama/nama barang tidak ditemukan pada tabel items. Periksa nama kolom dan izin SELECT.');return itemsRemoteColumns}
function toRemote(table,rec){const user_id=authUser?.id;if(table==='products'){const values={id:rec.id,user_id,code:rec.code,name:rec.name,category:rec.category,price:Number(rec.price)||0,stock:Number(rec.stock)||0,unit:rec.unit||'Pcs',supplier:rec.supplier||null,image:rec.image||null,notes:rec.notes||null,created_at:new Date().toISOString(),updated_at:new Date().toISOString()};const out={};for(const [field,aliases] of Object.entries(ITEM_COLUMN_ALIASES)){const col=itemsRemoteColumns?aliases.find(x=>itemsRemoteColumns.has(x)):aliases[0];if(!col||field==='id'||field==='created_at')continue;if(Object.hasOwn(values,field)&&values[field]!==undefined)out[col]=values[field]}return out}if(table==='categories')return{id:rec.id,user_id,name:rec.name,description:rec.description||null};return{id:rec.id,user_id,name:rec.name,contact:rec.contact||null,email:rec.email||null,address:rec.address||null}}
function fromRemote(table,rec){if(table==='products'){const pick=(...keys)=>{for(const k of keys)if(rec[k]!==undefined&&rec[k]!==null)return rec[k];return ''};const name=pick('name','item_name','product_name','title','nama_barang','nama');return{id:String(pick('id','item_id')||crypto.randomUUID()),code:String(pick('code','item_code','sku','sku_code','kode_barang','kode')),name:String(name),category:String(pick('category','category_name','kategori')),price:Number(pick('price','sell_price','unit_price','harga'))||0,stock:Number(pick('stock','quantity','qty','stok','jumlah'))||0,unit:String(pick('unit','satuan')||'Pcs'),supplier:String(pick('supplier','supplier_name','pemasok')),notes:String(pick('notes','description','deskripsi','keterangan')),image:String(pick('image','image_url','gambar','photo','foto')),updatedAt:String(pick('updated_at','updatedAt','updated_on','created_at')||todayISO()).slice(0,10),icon:/mouse/i.test(name)?'mouse':/keyboard/i.test(name)?'keyboard':/printer/i.test(name)?'printer':/laptop|komputer|monitor/i.test(name)?'laptop':'box'}}return table==='categories'?{id:String(rec.id),name:rec.name||'',description:rec.description||''}:{id:String(rec.id),name:rec.name||'',contact:rec.contact||'',email:rec.email||'',address:rec.address||''}}
async function supaRequest(table,method,rec){const remoteTable=table==='products'?supa.productsTable:table==='categories'?supa.categoriesTable:supa.suppliersTable;const url=`${supa.url}/rest/v1/${encodeURIComponent(remoteTable)}${method==='delete'||method==='update'?`?id=eq.${encodeURIComponent(rec.id)}`:''}`;const headers={apikey:supa.key,Authorization:`Bearer ${authToken||supa.key}`,Prefer:method==='insert'?'return=representation':'return=minimal'};if(method!=='delete')headers['Content-Type']='application/json';const request=payload=>fetch(url,{method:method==='insert'?'POST':method==='update'?'PATCH':'DELETE',headers,...(method==='delete'?{}:{body:JSON.stringify(payload)})});let r=await request(method==='delete'?null:toRemote(table,rec));if(!r.ok){let raw=await r.text();let err={};try{err=JSON.parse(raw)}catch{}if(method==='insert'&&table==='products'&&err.code==='23502'&&/column \"id\"/i.test(err.message||'')){const idColumn=[...(itemsRemoteColumns||[])].find(c=>c==='id')||'id';r=await request({...toRemote(table,rec),[idColumn]:crypto.randomUUID()});if(!r.ok){raw=await r.text();let second={};try{second=JSON.parse(raw)}catch{}if(['22P02','22003'].includes(second.code)&&/integer|bigint|smallint/i.test(second.message||'')){r=await request({...toRemote(table,rec),[idColumn]:Math.floor(Date.now()/1000)+Math.floor(Math.random()*1000)});if(!r.ok){raw=await r.text();throw new Error(`Supabase ${r.status}: ${raw.slice(0,170)}. Atur kolom id agar punya identity/default; cek query kolom di supabase-items-rls.sql.`)}}else throw new Error(`Supabase ${r.status}: ${raw.slice(0,170)}. Cek tipe dan default kolom id di Supabase.`)}}else throw new Error(`Supabase ${r.status}: ${raw.slice(0,170)}`)}if(method==='insert'&&table==='products'){const rows=await r.json().catch(()=>[]);if(rows[0]?.id!==undefined){rec.id=String(rows[0].id);db.products=db.products.map(p=>p.code===rec.code?{...p,id:rec.id}:p);saveData()}}}
async function persistRemote(table,rec,operation){if(!supa)return{ok:true,local:true};const remoteTable=table==='products'?supa.productsTable:table==='categories'?supa.categoriesTable:supa.suppliersTable;if(!remoteTable)return{ok:true,local:true};try{await supaRequest(table,operation==='insert'?'insert':operation==='update'?'update':'delete',rec);return{ok:true,local:false}}catch(e){return{ok:false,local:false,error:e.message}}}
function notifyPersist(result,message){if(result?.ok)toast(message+(result.local?' Tersimpan lokal; tabel cloud terkait belum disiapkan.':' Tersinkron ke Supabase.'),'success');else toast(`${message} Supabase: ${result?.error||'terjadi kesalahan'}`,'error')}
async function syncFromRemote(){if(!supa)return;const tables=[['products',supa.productsTable],['categories',supa.categoriesTable],['suppliers',supa.suppliersTable]].filter(([,tbl])=>String(tbl||'').trim());for(const [key,tbl] of tables){const r=await fetch(`${supa.url}/rest/v1/${encodeURIComponent(tbl)}?select=*`,{headers:{apikey:supa.key,Authorization:`Bearer ${authToken||supa.key}`}});if(!r.ok)throw new Error(`Tidak bisa membaca tabel ${tbl} (${r.status}). Pastikan kolom dan kebijakan RLS tersedia.`);const rows=await r.json();if(key==='products')itemsRemoteColumns=rows.length?new Set(Object.keys(rows[0])):await discoverItemsColumns();db[key]=rows.map(x=>fromRemote(key,x))}saveData()}
async function runSync(){if(!supa){toast('Hubungkan Supabase terlebih dahulu.');return}try{await syncFromRemote();render();toast('Data berhasil disinkronkan dari Supabase.')}catch(e){toast(e.message)}}
function exportCsv(){const headers=['Kode','Nama Barang','Kategori','Harga','Stok','Satuan','Supplier','Tanggal Update'];const rows=db.products.map(p=>[p.code,p.name,p.category,p.price,p.stock,p.unit,p.supplier,p.updatedAt]);const csv='\ufeff'+[headers,...rows].map(row=>row.map(v=>`"${String(v??'').replaceAll('"','""')}"`).join(',')).join('\r\n');const blob=new Blob([csv],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`zaven-inventaris-${todayISO()}.csv`;a.click();URL.revokeObjectURL(a.href);toast('File CSV berhasil diunduh.')}
function resetDemo(){if(!confirm('Pulihkan data contoh? Perubahan lokal saat ini akan diganti.'))return;db=structuredClone(sample);saveData();closeModal();render();toast('Data demo berhasil dipulihkan.')}
function editProfile(){const body=`<form id="profile-form" class="form-grid">${field('Nama lengkap','f-profile-name',currentUserName(),'text',{full:true})}</form>`;modal('Ubah Profil','Atur nama administrator yang ditampilkan.',body,`<button class="btn" data-action="close-modal">Batal</button><button class="btn btn-primary" data-submit="profile">Simpan</button>`);$('#profile-form').addEventListener('submit',e=>{e.preventDefault();const name=$('#f-profile-name').value.trim();if(authToken)sessionStorage.setItem('zaven-display-name',name);else localStorage.setItem('zaven-profile-name',name);closeModal();render();toast('Profil berhasil disimpan.','success')})}
function notify(){modal('Notifikasi','Status persediaan saat ini.',lowStock().length?`<div class="settings-stack">${lowStock().map(p=>`<div class="stock-row">${thumb(p)}<div class="item-info"><strong>${esc(p.name)}</strong><span>${esc(p.code)} · ${esc(p.category)}</span></div>${statusBadge(p)}</div>`).join('')}</div>`:`<div class="empty-state">${I('check',25)}<b>Semua aman</b><span>Tidak ada notifikasi stok saat ini.</span></div>`, `<button class="btn btn-primary" data-action="close-modal">Mengerti</button>`)}
function installHelp(){
  const ua=navigator.userAgent||'';
  let instructions='';
  if(/iPhone|iPad|iPod/i.test(ua)) instructions='<p class="install-platform-label">Petunjuk untuk iPhone/iPad (Safari)</p><ol><li>Buka halaman ini di <b>Safari</b>.</li><li>Tekan tombol <b>Bagikan</b> (ikon kotak dengan panah).</li><li>Pilih <b>Tambahkan ke Layar Utama</b>, lalu tekan <b>Tambah</b>.</li></ol>';
  else if(/Android/i.test(ua)) instructions='<p class="install-platform-label">Petunjuk untuk Android</p><ol><li>Buka menu browser <b>⋮</b> di kanan atas.</li><li>Pilih <b>Instal aplikasi</b> atau <b>Tambahkan ke layar utama</b>.</li><li>Konfirmasi dengan menekan <b>Instal</b> atau <b>Tambahkan</b>.</li></ol>';
  else instructions='<p class="install-platform-label">Petunjuk untuk desktop</p><ol><li>Pada Chrome/Edge, pilih ikon <b>Instal</b> di ujung kolom alamat; atau</li><li>Buka menu browser lalu pilih <b>Instal ZAVEN</b> / <b>Instal halaman sebagai aplikasi</b>.</li><li>Konfirmasi pemasangan.</li></ol>';
  modal('Pasang ZAVEN di perangkat','Tambahkan ZAVEN ke layar utama atau desktop agar bisa dibuka seperti aplikasi.',`<div class="install-help"><div class="settings-intro"><div class="settings-intro-icon">${I('download',19)}</div><div><strong>Instal ZAVEN Smart Inventory</strong><p>Ikon ZAVEN akan tampil di layar utama atau desktop setelah pemasangan.</p></div></div>${instructions}<p class="install-note">Pastikan membuka situs melalui HTTPS di browser yang mendukung pemasangan aplikasi.</p></div>`,`<button class="btn btn-primary" data-action="close-modal">Mengerti</button>`);
}
async function installZaven(){
  if(zavenInstalled){toast('ZAVEN sudah terpasang di perangkat ini.','success');return}
  if(!deferredInstallPrompt){installHelp();return}
  const promptEvent=deferredInstallPrompt;
  deferredInstallPrompt=null;
  try{
    await promptEvent.prompt();
    const result=await promptEvent.userChoice;
    if(result?.outcome==='accepted'){
      zavenInstalled=true;removeInstallButtons();toast('ZAVEN berhasil dipasang.','success');
    }else toast('Pemasangan belum diselesaikan. Anda bisa mencobanya lagi kapan saja.');
  }catch(error){console.warn('Dialog instalasi tidak tersedia:',error);installHelp()}
}
function handleAction(action,el){switch(action){case'install-app':installZaven();break;case'add-product':productModal();break;case'pick-image':$('#f-image')?.click();break;case'clear-image':pendingProductImage='';refreshProductImagePreview();break;case'add-category':categoryModal();break;case'add-supplier':supplierModal();break;case'settings':activePage='settings';closeModal();render();break;case'profile':activePage='profile';closeModal();render();break;case'group-profile':groupProfileModal();break;case'export':exportCsv();break;case'supabase':supabaseModal();break;case'connect-supabase':connectSupabase();break;case'close-modal':closeModal();break;case'sync':runSync();break;case'disconnect':if(confirm('Putuskan koneksi Supabase? Data yang sudah diunduh tetap tersimpan di perangkat ini.')){supa=null;localStorage.removeItem(CONFIG);render();toast('Koneksi Supabase diputuskan.')}break;case'reset-demo':resetDemo();break;case'notifications':notify();break;case'edit-profile':editProfile();break;case'logout':authToken='';authUser=null;sessionStorage.removeItem('zaven-access-token');sessionStorage.removeItem('zaven-auth-user');sessionStorage.removeItem('zaven-session');sessionStorage.removeItem('zaven-display-name');activePage='overview';render();toast('Anda telah keluar.');break;case'demo-entry':sessionStorage.setItem('zaven-session','demo');authToken='';authUser=null;activePage='overview';render();toast('Mode demo lokal aktif.');break;case'setup-from-login':supabaseModal();break;case'toggle-password':{const p=$('#login-password');if(p){const show=p.type==='password';p.type=show?'text':'password';el.textContent=show?'Sembunyikan':'Tampilkan'}break}case'forgot-password':sendPasswordReset();break;case'copy-sql':navigator.clipboard?.writeText(SQL_SETUP).then(()=>toast('SQL tersalin ke clipboard.')).catch(()=>toast('Clipboard tidak tersedia. Salin SQL secara manual.'));break;default:break}}
async function sendPasswordReset(){const email=$('#login-email')?.value.trim();if(!supa){$('#login-error').textContent='Atur koneksi Supabase terlebih dahulu untuk mengirim tautan reset kata sandi.';return}if(!email){$('#login-error').textContent='Masukkan email terlebih dahulu untuk menerima tautan reset.';$('#login-email')?.focus();return}try{const r=await fetch(`${supa.url}/auth/v1/recover`,{method:'POST',headers:{apikey:supa.key,'Content-Type':'application/json'},body:JSON.stringify({email,redirect_to:location.origin})});if(!r.ok)throw new Error('Permintaan reset gagal. Periksa konfigurasi email Supabase.');$('#login-error').textContent='Tautan reset telah diminta. Periksa kotak masuk email Anda.'}catch(e){$('#login-error').textContent=e.message||'Tidak dapat meminta reset kata sandi.'}}
document.addEventListener('click',e=>{const nav=e.target.closest('[data-page]');if(nav){activePage=nav.dataset.page;closeModal();render();return}const action=e.target.closest('[data-action]');if(action){handleAction(action.dataset.action,action);return}const editP=e.target.closest('[data-edit-product]');if(editP){productModal(editP.dataset.editProduct);return}const editC=e.target.closest('[data-edit-category]');if(editC){categoryModal(editC.dataset.editCategory);return}const editS=e.target.closest('[data-edit-supplier]');if(editS){supplierModal(editS.dataset.editSupplier);return}const delP=e.target.closest('[data-delete-product]');if(delP){confirmDelete('product',delP.dataset.deleteProduct);return}const delC=e.target.closest('[data-delete-category]');if(delC){confirmDelete('category',delC.dataset.deleteCategory);return}const delS=e.target.closest('[data-delete-supplier]');if(delS){confirmDelete('supplier',delS.dataset.deleteSupplier);return}const submit=e.target.closest('[data-submit]');if(submit){e.preventDefault();if(submit.dataset.submit==='product')saveProduct($('[data-edit-product-id]')?.value||$('#product-form')?.dataset.editId||null);if(submit.dataset.submit==='category')saveCategory($('#category-form')?.dataset.editId||null);if(submit.dataset.submit==='supplier')saveSupplier($('#supplier-form')?.dataset.editId||null);if(submit.dataset.submit==='profile')$('#profile-form')?.requestSubmit();return}const del=e.target.closest('[data-confirm-delete]');if(del){const [kind,id]=del.dataset.confirmDelete.split(':');deleteRec(kind,id)}});
document.addEventListener('submit',e=>{if(e.target.id==='login-form'){e.preventDefault();loginWithSupabase()}if(e.target.id==='product-form'){e.preventDefault();saveProduct(e.target.dataset.editId||null)}if(e.target.id==='category-form'){e.preventDefault();saveCategory(e.target.dataset.editId||null)}if(e.target.id==='supplier-form'){e.preventDefault();saveSupplier(e.target.dataset.editId||null)}});
function rerenderAndRestoreInput(id,position){render();const input=$(`#${id}`);if(input){input.focus();input.setSelectionRange(position,position)}}
document.addEventListener('input',e=>{if(e.target.id==='global-search'){query=e.target.value;if(query.trim()&&activePage!=='products')activePage='products';if(activePage==='products')rerenderAndRestoreInput('global-search',e.target.selectionStart??query.length)}if(e.target.id==='product-search'){query=e.target.value;rerenderAndRestoreInput('product-search',e.target.selectionStart??query.length)}});
document.addEventListener('change',e=>{if(e.target.id==='f-image'&&e.target.files?.[0]){onProductImageSelected(e.target.files[0]);return}if(e.target.id==='stock-filter'){productFilter=e.target.value;render()} });
function renderSearchOnly(){if(activePage==='overview'){return}render()}
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&activeModal)closeModal();if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#global-search')?.focus()}});
window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();deferredInstallPrompt=event;});
window.addEventListener('appinstalled',()=>{zavenInstalled=true;deferredInstallPrompt=null;removeInstallButtons();toast('ZAVEN berhasil dipasang.','success')});
render();
window.setTimeout(()=>{splashComplete=true;render()},1100);
if('serviceWorker'in navigator&&location.protocol!=='file:')window.addEventListener('load',()=>{const appBase=new URL('./',location.href);navigator.serviceWorker.register(new URL('service-worker.js',appBase)).catch(err=>console.info('PWA offline worker belum aktif:',err))});
if(supa&&authToken)syncFromRemote().then(()=>{if(hasAppSession())render()}).catch(e=>{console.warn(e);authToken='';sessionStorage.removeItem('zaven-access-token');sessionStorage.removeItem('zaven-auth-user');sessionStorage.removeItem('zaven-session');render();toast('Sesi cloud berakhir; silakan masuk kembali.')});
